-- Name: has_app_role(text, text); Type: FUNCTION; Schema: app_security; Owner: -
--

CREATE FUNCTION app_security.has_app_role(app_param text, role_param text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from company_os.app_access a
    join company_os.people p on p.id = a.person_id
    where p.auth_user_id = auth.uid()
      and a.app = app_param
      and a.role = role_param
      and a.revoked_at is null);
$$;


--
-- Name: FUNCTION has_app_role(app_param text, role_param text); Type: COMMENT; Schema: app_security; Owner: -
--

COMMENT ON FUNCTION app_security.has_app_role(app_param text, role_param text) IS 'The one authorisation contract every APA app calls. Resolves auth.uid() to a person, then to a live grant. STABLE, so Postgres caches it per statement - which is why a table lookup costs nothing next to JWT claims, and unlike claims a revocation takes effect on the next request with no token refresh.';


--
-- Name: assign_equipment(uuid, uuid, date, text, text, text); Type: FUNCTION; Schema: company_os; Owner: -
--

CREATE FUNCTION company_os.assign_equipment(p_equipment_id uuid, p_person_id uuid, p_assigned_at date DEFAULT CURRENT_DATE, p_condition_out text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_actor text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'company_os', 'extensions', 'pg_catalog'
    AS $$
declare
  v_open_id uuid;
  v_open_person uuid;
  v_open_start date;
  v_new_id uuid;
begin
  select id, person_id, assigned_at
    into v_open_id, v_open_person, v_open_start
    from company_os.equipment_assignments
   where equipment_id = p_equipment_id and returned_at is null
   for update;

  if v_open_person = p_person_id then
    return v_open_id;
  end if;

  if v_open_id is not null then
    update company_os.equipment_assignments
       set returned_at = greatest(p_assigned_at, v_open_start)
     where id = v_open_id;
  end if;

  insert into company_os.equipment_assignments
    (equipment_id, person_id, assigned_at, condition_out, note, created_by)
  values
    (p_equipment_id, p_person_id, p_assigned_at, p_condition_out, p_note, p_actor)
  returning id into v_new_id;

  update company_os.equipment
     set current_holder_id = p_person_id,
         status = 'in_use',
         updated_at = now()
   where id = p_equipment_id;

  return v_new_id;
end;
$$;


