CREATE FUNCTION htt.resolve_contributor(p_email text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'extensions', 'pg_catalog'
    AS $$
  select coalesce(
    (select pge.person_id
       from company_os.person_git_emails pge
