--
-- Name: admin_org_directory(); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.admin_org_directory() RETURNS TABLE(id uuid, slug text, name text, status text, created_at timestamp with time zone, learner_seats integer, seats_used integer, learner_count integer, manager_count integer, open_invite_count integer, deactivated_count integer, manager_user_id uuid, manager_name text, manager_email text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- service_role is a trusted server-side caller: it reaches this only
  -- from code that has already run `requireAdmin`, and it can read every
  -- underlying table directly regardless. Refusing it bought no safety
  -- and broke the page. (Same reasoning as 008 on org_seat_usage.)
  if not (
    auth.role() = 'service_role'
    or payroll_iq.is_admin()
  ) then
    raise exception 'not authorised to list organisations'
      using errcode = 'insufficient_privilege';
  end if;

  return query
    select
      o.id,
      o.slug,
      o.name,
      o.status,
      o.created_at,
      o.learner_seats,
      payroll_iq.org_seats_used(o.id),
      (select count(*)::integer from payroll_iq.users u
        where u.org_id = o.id and u.status = 'active' and u.is_learner),
      (select count(*)::integer from payroll_iq.users u
        where u.org_id = o.id and u.status = 'active' and u.role = 'manager'),
      (select count(*)::integer from payroll_iq.invites i
        where i.org_id = o.id
          and i.released_at is null
          and i.expires_at > now()),
      (select count(*)::integer from payroll_iq.users u
        where u.org_id = o.id and u.status = 'deactivated'),
      m.id,
      m.full_name,
      m.email
    from payroll_iq.organisations o
    left join lateral (
      select u.id, u.full_name, u.email
        from payroll_iq.users u
       where u.org_id = o.id
         and u.role = 'manager'
         and u.status = 'active'
       order by u.created_at asc
       limit 1
    ) m on true
    order by o.name asc;
end;
$$;


--
-- Name: FUNCTION admin_org_directory(); Type: COMMENT; Schema: payroll_iq; Owner: -
--

COMMENT ON FUNCTION payroll_iq.admin_org_directory() IS 'Cross-organisation directory for the admin console. Seat occupancy comes from payroll_iq.org_seats_used so it agrees with the enforcement trigger and the manager console. Admin only.';


--
-- Name: assert_org_within_seats(uuid); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.assert_org_within_seats(p_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_seats integer;
  v_used  integer;
begin
  -- Admins are orgless by CHECK and never learners; nothing to enforce.
  if p_org_id is null then
    return;
  end if;

  select o.learner_seats into v_seats
    from payroll_iq.organisations o
   where o.id = p_org_id
     for update;

  -- No org row: the foreign key will raise a better error than we can.
  if v_seats is null then
    return;
  end if;

  v_used := payroll_iq.org_seats_used(p_org_id);

  if v_used > v_seats then
    raise exception 'seat_limit_reached: % of % seats in use', v_used, v_seats
      using errcode = 'check_violation',
            hint = 'seat_limit_reached';
  end if;
end;
$$;


--
-- Name: enforce_org_seat_capacity(); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.enforce_org_seat_capacity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform payroll_iq.assert_org_within_seats(new.id);
  return null;
end;
$$;


--
-- Name: enforce_seat_capacity(); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.enforce_seat_capacity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform payroll_iq.assert_org_within_seats(new.org_id);
  return null;
end;
$$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_security.has_app_role('payroll_iq', 'admin');
$$;


--
-- Name: FUNCTION is_admin(); Type: COMMENT; Schema: payroll_iq; Owner: -
--

COMMENT ON FUNCTION payroll_iq.is_admin() IS 'Delegates to app_security.has_app_role. payroll_iq.users.role no longer carries authorisation - it is membership only. Changing who is an admin is now an INSERT or a revoked_at stamp in company_os.app_access, with no deploy.';


--
-- Name: is_org_manager(uuid); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.is_org_manager(org_param uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from payroll_iq.users u
    where u.id = auth.uid()
      and u.org_id = org_param
      and u.status = 'active'
      and u.role = 'manager'
  );
$$;


--
-- Name: is_org_member(uuid); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.is_org_member(org_param uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from payroll_iq.users u
    where u.id = auth.uid()
      and u.org_id = org_param
      and u.status = 'active'
  );
$$;


--
-- Name: learner_owns(uuid); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.learner_owns(learner_param uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select auth.uid() = learner_param;
$$;


--
-- Name: manages_learner(uuid); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.manages_learner(learner_param uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from payroll_iq.users target
    join payroll_iq.users caller
      on caller.org_id = target.org_id
    where target.id = learner_param
      and caller.id = auth.uid()
      and caller.status = 'active'
      and caller.role = 'manager'
  );
$$;


--
-- Name: org_seat_usage(uuid); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.org_seat_usage(p_org_id uuid) RETURNS TABLE(learner_seats integer, seats_used integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- service_role is a trusted server-side caller: it reaches this only
  -- from code that has already run `requireOrgManager`, and it can read
  -- both underlying tables directly regardless. Refusing it bought no
  -- safety and broke the page.
  if not (
    auth.role() = 'service_role'
    or payroll_iq.is_admin()
    or payroll_iq.is_org_member(p_org_id)
  ) then
    raise exception 'not authorised to read seat usage for this organisation'
      using errcode = 'insufficient_privilege';
  end if;

  return query
    select o.learner_seats,
           payroll_iq.org_seats_used(o.id)
      from payroll_iq.organisations o
     where o.id = p_org_id;
end;
$$;


--
-- Name: org_seats_used(uuid); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.org_seats_used(p_org_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (
    (select count(*)
       from payroll_iq.users u
      where u.org_id = p_org_id
        and u.status = 'active'
        and u.is_learner)
  + (select count(*)
       from payroll_iq.invites i
      where i.org_id = p_org_id
        and i.is_learner
        and i.released_at is null
        and i.expires_at > now())
  )::integer;
$$;


--
-- Name: FUNCTION org_seats_used(p_org_id uuid); Type: COMMENT; Schema: payroll_iq; Owner: -
--

COMMENT ON FUNCTION payroll_iq.org_seats_used(p_org_id uuid) IS 'Seats currently occupied: active learners plus open learner invites. The single definition of occupancy — the enforcement trigger and the manager console both call this so they cannot disagree.';


--
-- Name: organisations_guard_billing(); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.organisations_guard_billing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or payroll_iq.is_admin() then
    return new;
  end if;

  if new.billing_lane              is distinct from old.billing_lane
  or new.billing_state             is distinct from old.billing_state
  or new.paid_through              is distinct from old.paid_through
  or new.grace_ends_on             is distinct from old.grace_ends_on
  or new.stripe_customer_id        is distinct from old.stripe_customer_id
  or new.stripe_subscription_id    is distinct from old.stripe_subscription_id
  or new.hubspot_invoice_ref       is distinct from old.hubspot_invoice_ref
  or new.seat_price_override_cents is distinct from old.seat_price_override_cents then
    raise exception 'only an administrator may change billing fields'
      using errcode = 'insufficient_privilege';
  end if;

  return new;
end;
$$;


--
-- Name: organisations_guard_seats(); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.organisations_guard_seats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or payroll_iq.is_admin() then
    return new;
  end if;

  if new.learner_seats > old.learner_seats then
    raise exception 'only an administrator may add seats'
      using errcode = 'insufficient_privilege',
            hint = 'seat_increase_requires_admin';
  end if;

  if new.learner_seats < old.learner_seats
     and not payroll_iq.is_org_manager(old.id) then
    raise exception 'only an org manager or administrator may change seats'
      using errcode = 'insufficient_privilege';
  end if;

  return new;
end;
$$;


