--
-- Name: search_modules(text, text, integer, boolean, uuid[]); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.search_modules(p_query text, p_track text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_cross_track boolean DEFAULT false, p_topic_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(module_id uuid, title text, description text, duration_seconds integer, poster_url text, version integer, tracks text[], status text, relevance real, matched_topics text[])
    LANGUAGE sql STABLE
    SET search_path TO 'payroll_iq', 'extensions'
    AS $$
  with tagged as (
    select
      m.id,
      m.title,
      m.description,
      m.duration_seconds,
      m.poster_url,
      m.version,
      m.status,
      m.search,
      array_agg(distinct t.track)                as tracks,
      array_agg(distinct t.name order by t.name) as topic_names,
      bool_or(p_topic_ids is null or t.id = any (p_topic_ids)) as topic_in_scope
    from payroll_iq.modules m
    join payroll_iq.module_topics mt on mt.module_id = m.id
    join payroll_iq.topics t         on t.id = mt.topic_id
    where m.status = 'published'
    group by m.id
  )
  select
    tg.id               as module_id,
    tg.title,
    tg.description,
    tg.duration_seconds,
    tg.poster_url,
    tg.version,
    tg.tracks,
    tg.status,
    (
      coalesce(
        pg_catalog.ts_rank_cd(
          tg.search,
          pg_catalog.websearch_to_tsquery('english', p_query)
        ),
        0
      )
      + coalesce(similarity(tg.title, p_query), 0)
    )::real             as relevance,
    tg.topic_names      as matched_topics
  from tagged tg
  where
    tg.topic_in_scope
    and (
      p_cross_track
      or p_track is null
      or p_track = any (tg.tracks)
    )
    and (
      tg.search @@ pg_catalog.websearch_to_tsquery('english', p_query)
      or similarity(tg.title, p_query) > 0.3
    )
  order by relevance desc, tg.title asc
  limit greatest(0, least(p_limit, 50));
$$;


--
-- Name: FUNCTION search_modules(p_query text, p_track text, p_limit integer, p_cross_track boolean, p_topic_ids uuid[]); Type: COMMENT; Schema: payroll_iq; Owner: -
--

COMMENT ON FUNCTION payroll_iq.search_modules(p_query text, p_track text, p_limit integer, p_cross_track boolean, p_topic_ids uuid[]) IS 'Combined tsvector + trigram search over published modules, ordered by ts_rank_cd + similarity, capped at 50. Reads the GENERATED modules.search column. Tracks and topic names derive through module_topics rather than being cached on the row. p_topic_ids is the already-state-scoped topic list from scopeTopicsToStates — NULL means unscoped (the only caller today), an empty array means nothing in scope.';


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: topics_one_level_deep(); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.topics_one_level_deep() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.parent_id is null then
    return new;
  end if;

  if exists (
    select 1 from payroll_iq.topics p
     where p.id = new.parent_id
       and p.parent_id is not null
  ) then
    raise exception
      'topic hierarchy is one level deep: % already has a parent, so it cannot be one',
      new.parent_id
      using errcode = 'check_violation', hint = 'topic_depth_exceeded';
  end if;

  if exists (
    select 1 from payroll_iq.topics c
     where c.parent_id = new.id
  ) then
    raise exception
      'topic hierarchy is one level deep: this topic already has sub-topics, so it cannot become one'
      using errcode = 'check_violation', hint = 'topic_depth_exceeded';
  end if;

  return new;
end;
$$;


--
-- Name: touch_last_seen(); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.touch_last_seen() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null then
    return;
  end if;
  update payroll_iq.users
     set last_seen_at = now()
   where id = auth.uid()
     and status = 'active'
     and (last_seen_at is null
       or last_seen_at < now() - interval '1 hour');
end;
$$;


--
-- Name: FUNCTION touch_last_seen(); Type: COMMENT; Schema: payroll_iq; Owner: -
--

COMMENT ON FUNCTION payroll_iq.touch_last_seen() IS 'Record that the calling user is here, at most once an hour. No-ops otherwise, so it is safe to call on every authenticated page render.';


--
-- Name: users_guard_privileged_columns(); Type: FUNCTION; Schema: payroll_iq; Owner: -
--

CREATE FUNCTION payroll_iq.users_guard_privileged_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or payroll_iq.is_admin() then
    return new;
  end if;

  if new.role   is distinct from old.role
  or new.org_id is distinct from old.org_id
  or new.email  is distinct from old.email then
    raise exception 'only admins may change role, org, or email';
  end if;

  if new.status is distinct from old.status
     and not (old.org_id is not null
              and payroll_iq.is_org_manager(old.org_id)) then
    raise exception 'only an org manager or admin may change member status';
  end if;

  return new;
end;
$$;


