--
-- Name: consultant_load; Type: VIEW; Schema: company_os; Owner: -
--

CREATE VIEW company_os.consultant_load AS
 WITH weeks AS (
         SELECT (gs.gs)::date AS week_start,
            ((gs.gs)::date + 6) AS week_end
           FROM generate_series(date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone), (date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone) + '49 days'::interval), '7 days'::interval) gs(gs)
        ), members AS (
         SELECT tm.id AS team_member_id,
            tm.person_id,
            p.display_name
           FROM (company_os.team_members tm
             JOIN company_os.people p ON ((p.id = tm.person_id)))
          WHERE (tm.status = 'active'::text)
        ), horizon_days AS (
         SELECT (g.d)::date AS day
           FROM generate_series(((date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone))::date)::timestamp with time zone, (((date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone))::date + 55))::timestamp with time zone, '1 day'::interval) g(d)
          WHERE (EXTRACT(isodow FROM g.d) < (6)::numeric)
        ), leave_days AS (
         SELECT t.team_member_id,
            (date_trunc('week'::text, (hd.day)::timestamp with time zone))::date AS week_start,
            count(*) AS leave_days
           FROM (horizon_days hd
             JOIN company_os.time_off t ON (((t.status = ANY (ARRAY['approved'::text, 'taken'::text])) AND ((hd.day >= t.start_date) AND (hd.day <= t.end_date)))))
          GROUP BY t.team_member_id, ((date_trunc('week'::text, (hd.day)::timestamp with time zone))::date)
        ), alloc AS (
         SELECT sa.team_member_id,
            w_1.week_start,
            sum(
                CASE
                    WHEN (sa.schedule_status = 'confirmed'::text) THEN COALESCE(sa.allocation_hours, (0)::numeric)
                    ELSE (0)::numeric
                END) AS confirmed_hours,
            sum(
                CASE
                    WHEN (sa.schedule_status = 'tentative'::text) THEN COALESCE(sa.allocation_hours, (0)::numeric)
                    ELSE (0)::numeric
                END) AS tentative_hours
           FROM (company_os.staff_assignments sa
             JOIN weeks w_1 ON (((sa.start_date <= w_1.week_end) AND ((sa.end_date IS NULL) OR (sa.end_date >= w_1.week_start)))))
          WHERE ((sa.allocation_hours IS NOT NULL) AND ((sa.board_id IS NOT NULL) OR (sa.source_deal_id IS NOT NULL)))
          GROUP BY sa.team_member_id, w_1.week_start
        )
 SELECT m.person_id,
    m.team_member_id,
    m.display_name,
    w.week_start,
    (38)::numeric AS capacity_hours,
    (((COALESCE(ld.leave_days, (0)::bigint))::numeric * (38.0 / (5)::numeric)))::numeric(6,2) AS leave_hours,
    (GREATEST(((38)::numeric - ((COALESCE(ld.leave_days, (0)::bigint))::numeric * (38.0 / (5)::numeric))), (0)::numeric))::numeric(6,2) AS available_hours,
    (COALESCE(a.confirmed_hours, (0)::numeric))::numeric(6,2) AS confirmed_hours,
    (COALESCE(a.tentative_hours, (0)::numeric))::numeric(6,2) AS tentative_hours,
    round(((COALESCE(a.confirmed_hours, (0)::numeric) / NULLIF(GREATEST(((38)::numeric - ((COALESCE(ld.leave_days, (0)::bigint))::numeric * (38.0 / (5)::numeric))), (0)::numeric), (0)::numeric)) * (100)::numeric), 1) AS confirmed_utilisation_pct,
    round((((COALESCE(a.confirmed_hours, (0)::numeric) + COALESCE(a.tentative_hours, (0)::numeric)) / NULLIF(GREATEST(((38)::numeric - ((COALESCE(ld.leave_days, (0)::bigint))::numeric * (38.0 / (5)::numeric))), (0)::numeric), (0)::numeric)) * (100)::numeric), 1) AS committed_plus_tentative_pct
   FROM (((members m
     CROSS JOIN weeks w)
     LEFT JOIN alloc a ON (((a.team_member_id = m.team_member_id) AND (a.week_start = w.week_start))))
     LEFT JOIN leave_days ld ON (((ld.team_member_id = m.team_member_id) AND (ld.week_start = w.week_start))));


--
-- Name: VIEW consultant_load; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON VIEW company_os.consultant_load IS 'Per person per week over a rolling 8 weeks: confirmed + tentative allocation vs capacity, leave subtracted. The two-tier overwork flag (soft >= 85%, hard > 100%) is applied in the app over confirmed_utilisation_pct.';


