--
-- Name: deal_forecast_load; Type: VIEW; Schema: company_os; Owner: -
--

CREATE VIEW company_os.deal_forecast_load AS
 WITH weeks AS (
         SELECT (gs.gs)::date AS week_start,
            ((gs.gs)::date + 6) AS week_end
           FROM generate_series(date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone), (date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone) + '49 days'::interval), '7 days'::interval) gs(gs)
        )
 SELECT sa.team_member_id,
    w.week_start,
    (sum(((COALESCE(sa.allocation_hours, (0)::numeric) * (COALESCE(d.probability, 0))::numeric) / 100.0)))::numeric(6,2) AS probability_weighted_hours
   FROM ((company_os.staff_assignments sa
     JOIN weeks w ON (((sa.start_date <= w.week_end) AND ((sa.end_date IS NULL) OR (sa.end_date >= w.week_start)))))
     JOIN company_os.deals d ON ((d.id = sa.source_deal_id)))
  WHERE ((sa.schedule_status = 'tentative'::text) AND (sa.allocation_hours IS NOT NULL))
  GROUP BY sa.team_member_id, w.week_start;


--
-- Name: VIEW deal_forecast_load; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON VIEW company_os.deal_forecast_load IS 'Probability-weighted expected load from tentative, deal-linked allocations. Leadership sees the committed picture (consultant_load) and the expected one (this) side by side.';


