--
-- Name: estimate_variance; Type: VIEW; Schema: company_os; Owner: -
--

CREATE VIEW company_os.estimate_variance AS
 SELECT b.id AS board_id,
    b.name,
    COALESCE((b.metadata ->> 'project_type'::text), '(unset)'::text) AS project_type,
    (COALESCE(est.estimated_hours, (0)::bigint))::numeric(10,2) AS estimated_hours,
    (COALESCE(te.logged_hours, (0)::numeric))::numeric(10,2) AS logged_hours,
    ((COALESCE(te.logged_hours, (0)::numeric) - (COALESCE(est.estimated_hours, (0)::bigint))::numeric))::numeric(10,2) AS variance_hours
   FROM ((company_os.boards b
     LEFT JOIN ( SELECT tasks.board_id,
            sum(tasks.human_tokens) AS estimated_hours
           FROM company_os.tasks
          WHERE ((tasks.archived_at IS NULL) AND (tasks.human_tokens IS NOT NULL))
          GROUP BY tasks.board_id) est ON ((est.board_id = b.id)))
     LEFT JOIN ( SELECT time_entry.board_id,
            sum(time_entry.hours) AS logged_hours
           FROM company_os.time_entry
          WHERE (time_entry.board_id IS NOT NULL)
          GROUP BY time_entry.board_id) te ON ((te.board_id = b.id)))
  WHERE (b.archived_at IS NULL);


--
-- Name: VIEW estimate_variance; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON VIEW company_os.estimate_variance IS 'Planned vs logged hours per project/project-type. Feeds back so each finished job sharpens the next estimate.';


