--
-- Name: project_budget_health; Type: VIEW; Schema: company_os; Owner: -
--

CREATE VIEW company_os.project_budget_health AS
 SELECT b.id AS board_id,
    b.name,
    b.budget_hours,
    (COALESCE(te.logged_hours, (0)::numeric))::numeric(10,2) AS logged_hours,
    ((b.budget_hours - COALESCE(te.logged_hours, (0)::numeric)))::numeric(10,2) AS remaining_budget_hours,
    (COALESCE(rem.remaining_estimate_hours, (0)::bigint))::numeric(10,2) AS remaining_estimate_hours,
    ((COALESCE(rem.remaining_estimate_hours, (0)::bigint))::numeric > (b.budget_hours - COALESCE(te.logged_hours, (0)::numeric))) AS over_budget_flag
   FROM ((company_os.boards b
     LEFT JOIN ( SELECT time_entry.board_id,
            sum(time_entry.hours) AS logged_hours
           FROM company_os.time_entry
          WHERE (time_entry.board_id IS NOT NULL)
          GROUP BY time_entry.board_id) te ON ((te.board_id = b.id)))
     LEFT JOIN ( SELECT t.board_id,
            sum(t.human_tokens) AS remaining_estimate_hours
           FROM (company_os.tasks t
             LEFT JOIN company_os.board_columns bc ON ((bc.id = t.board_column_id)))
          WHERE ((t.archived_at IS NULL) AND (t.human_tokens IS NOT NULL) AND (t.status <> 'done'::text) AND (t.completed_at IS NULL) AND (COALESCE(bc.is_done, false) = false))
          GROUP BY t.board_id) rem ON ((rem.board_id = b.id)))
  WHERE ((b.archived_at IS NULL) AND (b.budget_hours IS NOT NULL));


--
-- Name: VIEW project_budget_health; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON VIEW company_os.project_budget_health IS 'Fires over_budget_flag when remaining task estimate exceeds remaining budget hours — before the overrun, not after.';


--
-- Name: project_slip; Type: VIEW; Schema: company_os; Owner: -
--

CREATE VIEW company_os.project_slip AS
 SELECT b.id AS board_id,
    b.name,
    b.client_company_id,
    b.start_date,
    b.end_date,
    b.client_response_sla_days,
    (b.end_date - b.start_date) AS planned_days,
    (LEAST(CURRENT_DATE, COALESCE(b.end_date, CURRENT_DATE)) - b.start_date) AS elapsed_days,
    COALESCE(cr.days_waiting_on_client, (0)::bigint) AS days_waiting_on_client,
    COALESCE(cr.open_requests, (0)::bigint) AS open_requests
   FROM (company_os.boards b
     LEFT JOIN ( SELECT client_requests.board_id,
            sum((COALESCE(client_requests.answered_on, CURRENT_DATE) - client_requests.asked_on)) AS days_waiting_on_client,
            count(*) FILTER (WHERE (client_requests.answered_on IS NULL)) AS open_requests
           FROM company_os.client_requests
          GROUP BY client_requests.board_id) cr ON ((cr.board_id = b.id)))
  WHERE ((b.client_company_id IS NOT NULL) AND (b.archived_at IS NULL) AND (b.start_date IS NOT NULL));


--
-- Name: VIEW project_slip; Type: COMMENT; Schema: company_os; Owner: -
--

COMMENT ON VIEW company_os.project_slip IS 'Decomposes an overrun: planned vs elapsed alongside days-waiting-on-client, measured against the kickoff SLA. Days-waiting is derived here, never stored.';


--
-- Name: public_retreats; Type: VIEW; Schema: company_os; Owner: -
--

CREATE VIEW company_os.public_retreats AS
 SELECT cohort_slug AS id,
    cohort_slug,
    COALESCE(NULLIF(btrim(split_part(min(location), ','::text, 1)), ''::text), initcap(replace(cohort_slug, '-'::text, ' '::text))) AS name,
    min(location) AS location,
    min(date_start) AS date_start,
    max(date_end) AS date_end,
    count(DISTINCT id) AS tiers,
    bool_or(active) AS active,
    min(amount_usd_cents) AS from_usd_cents,
    ( SELECT COALESCE(sum(o.amount_usd_cents), (0)::numeric) AS "coalesce"
           FROM ((company_os.event_registrations r
             JOIN company_os.products p2 ON ((p2.id = r.product_id)))
             LEFT JOIN company_os.orders o ON ((o.id = r.order_id)))
          WHERE ((p2.cohort_slug = pr.cohort_slug) AND (r.status = 'confirmed'::text))) AS collected_usd_cents,
    ( SELECT count(*) AS count
           FROM (company_os.event_registrations r
             JOIN company_os.products p2 ON ((p2.id = r.product_id)))
          WHERE (p2.cohort_slug = pr.cohort_slug)) AS registrations,
    ( SELECT count(*) AS count
           FROM (company_os.event_registrations r
             JOIN company_os.products p2 ON ((p2.id = r.product_id)))
          WHERE ((p2.cohort_slug = pr.cohort_slug) AND (r.status = 'confirmed'::text))) AS confirmed
   FROM company_os.products pr
  WHERE ((type = 'event'::text) AND (cohort_slug IS NOT NULL))
  GROUP BY cohort_slug;


